import { randomUUID } from 'crypto';
import { ServerResponse, IncomingMessage } from 'http'; // Import IncomingMessage

export function generateId(): string {
  return randomUUID();
}

export function sendJsonResponse(res: ServerResponse, statusCode: number, data: object | string): void {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

export function sendErrorResponse(res: ServerResponse, statusCode: number, message: string): void {
  sendJsonResponse(res, statusCode, { error: message });
}

export function parseRequestBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk: Buffer) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        if (body) {
          resolve(JSON.parse(body));
        } else {
          resolve({});
        }
      } catch (error: any) { // Explicitly type error as any
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', (err: Error) => {
      reject(err);
    });
  });
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { EventBus } from './event-bus';
import { UserService } from './user-service';
import { ProjectService } from './project-service';
import { TaskService } from './task-service';
import { CommentService } from './comment-service';
import { NotificationService } from './notification-service';
import { ApiRouter } from './api-router';
import { sendErrorResponse } from './utils';

const PORT = process.env.PORT || 3000;

async function main() {
  const eventBus = new EventBus();

  const userService = new UserService();
  const projectService = new ProjectService(eventBus);
  const taskService = new TaskService(eventBus);
  const commentService = new CommentService(eventBus);
  const notificationService = new NotificationService(eventBus);

  const apiRouter = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
    // Enable CORS for demo purposes
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    try {
      await apiRouter.handleRequest(req, res);
    } catch (error: any) { // Explicitly type error as any
      console.error('Unhandled request error:', error);
      sendErrorResponse(res, 500, error.message || 'Internal Server Error');
    }
  });

  server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log('Available routes:');
    console.log('  GET /users, POST /users, GET/PUT/DELETE /users/:id');
    console.log('  GET /projects, POST /projects, GET/PUT/DELETE /projects/:id, POST/DELETE /projects/:id/members');
    console.log('  GET /tasks?projectId=xxx, POST /tasks, GET/PUT/DELETE /tasks/:id, PUT /tasks/:id/status, PUT /tasks/:id/assign');
    console.log('  GET /comments?taskId=xxx, POST /comments, GET/DELETE /comments/:id');
    console.log('  GET /notifications?userId=xxx, PUT /notifications/:id/read');
  });
}

main();

import { Comment, CommentId, TaskId, UserId } from './types';
import { EventBus } from './event-bus.js'; // Corrected import with .js extension
import { generateId } from './utils';

export class CommentService {
  private comments: Map<CommentId, Comment> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
    // Seed some initial data
    this.createComment({
      taskId: 'task1', // Assuming 'task1' is a valid TaskId for demo purposes
      authorId: 'user1', // Assuming 'user1' is a valid UserId
      text: 'Initial thoughts on the design approach.',
    });
  }

  public createComment(commentData: {
    taskId: TaskId;
    authorId: UserId;
    text: string;
  }): Comment {
    const newComment: Comment = {
      id: generateId(),
      createdAt: Date.now(),
      ...commentData,
    };
    this.comments.set(newComment.id, newComment);
    // The Event definition has a payload field.
    this.eventBus.publish({ name: 'comment.added', payload: { commentId: newComment.id, taskId: newComment.taskId, authorId: newComment.authorId } });
    return newComment;
  }

  public getComment(id: CommentId): Comment | undefined {
    return this.comments.get(id);
  }

  public getCommentsByTask(taskId: TaskId): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  public getAllComments(): Comment[] {
    return Array.from(this.comments.values());
  }

  public deleteComment(id: CommentId): boolean {
    return this.comments.delete(id);
  }
}

import {
  Notification,
  NotificationId,
  UserId,
  Event,
  TaskAssignedEvent,
  CommentAddedEvent,
  TaskStatusChangedEvent,
  ProjectMemberAddedEvent,
  TaskStatus,
} from './types';
import { EventBus } from './event-bus.js'; // Corrected import with .js extension
import { generateId } from './utils';

export class NotificationService {
  private notifications: Map<NotificationId, Notification> = new Map();
  private eventBus: EventBus;
  // In a real system, you'd likely fetch task details from TaskService if needed.
  // For this exercise, we'll manage a simplified mapping for assignee lookups.
  private taskAssigneeMap: Map<string, UserId> = new Map(); // taskId -> assigneeId for quick lookup

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
    this.setupEventListeners();
  }

  private setupEventListeners(): void {
    this.eventBus.subscribe('task.assigned', this.handleTaskAssigned.bind(this));
    this.eventBus.subscribe('comment.added', this.handleCommentAdded.bind(this));
    this.eventBus.subscribe('task.statusChanged', this.handleTaskStatusChanged.bind(this));
    this.eventBus.subscribe('project.memberAdded', this.handleProjectMemberAdded.bind(this));
  }

  private createNotification(userId: UserId, message: string): Notification {
    const newNotification: Notification = {
      id: generateId(),
      userId,
      message,
      read: false,
      createdAt: Date.now(),
    };
    this.notifications.set(newNotification.id, newNotification);
    return newNotification;
  }

  private handleTaskAssigned(event: Event): void {
    const payload = event.payload as TaskAssignedEvent;
    const { taskId, assigneeId, previousAssigneeId } = payload;

    this.taskAssigneeMap.set(taskId, assigneeId);

    if (previousAssigneeId && previousAssigneeId !== assigneeId) {
      this.createNotification(previousAssigneeId, `You have been unassigned from task ${taskId}.`);
    }
    this.createNotification(assigneeId, `You have been assigned to task ${taskId}.`);
  }

  private handleCommentAdded(event: Event): void {
    const payload = event.payload as CommentAddedEvent;
    const { taskId, authorId } = payload;
    const assigneeId = this.taskAssigneeMap.get(taskId);

    if (assigneeId && assigneeId !== authorId) {
      this.createNotification(assigneeId, `A new comment was added to task ${taskId} by ${authorId}.`);
    }
  }

  private handleTaskStatusChanged(event: Event): void {
    const payload = event.payload as TaskStatusChangedEvent;
    const { taskId, newStatus } = payload;
    const assigneeId = this.taskAssigneeMap.get(taskId);

    if (assigneeId) {
      this.createNotification(assigneeId, `The status of task ${taskId} has changed to ${newStatus}.`);
    }
  }

  private handleProjectMemberAdded(event: Event): void {
    const payload = event.payload as ProjectMemberAddedEvent;
    const { projectId, userId } = payload;
    this.createNotification(userId, `You have been added to project ${projectId}.`);
  }

  public getNotificationsByUserId(userId: UserId): Notification[] {
    return Array.from(this.notifications.values()).filter(notif => notif.userId === userId);
  }

  public markNotificationAsRead(id: NotificationId): Notification | undefined {
    const notification = this.notifications.get(id);
    if (notification) {
      notification.read = true;
      return notification;
    }
    return undefined;
  }

  public getAllNotifications(): Notification[] {
    return Array.from(this.notifications.values());
  }
}

import { Project, ProjectId, UserId } from './types';
import { EventBus } from './event-bus.js'; // Corrected import with .js extension
import { generateId } from './utils';

export class ProjectService {
  private projects: Map<ProjectId, Project> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
    // Seed some initial data
    const project1 = this.createProject({ name: 'Website Redesign', description: 'Redesign the company website' });
    if (project1) {
      // Using a placeholder for user ID. In a real system, you'd create a user first.
      // For demo purposes, we assume 'user1' exists or will be created by the demo script.
      this.addMember(project1.id, 'user1'); 
    }
  }

  public createProject(projectData: { name: string; description: string }): Project {
    const newProject: Project = {
      id: generateId(),
      name: projectData.name,
      description: projectData.description,
      memberIds: [],
    };
    this.projects.set(newProject.id, newProject);
    return newProject;
  }

  public getProject(id: ProjectId): Project | undefined {
    return this.projects.get(id);
  }

  public getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  public updateProject(id: ProjectId, updates: Partial<Omit<Project, 'id'>>): Project | undefined {
    const project = this.projects.get(id);
    if (project) {
      Object.assign(project, updates);
      return project;
    }
    return undefined;
  }

  public deleteProject(id: ProjectId): boolean {
    return this.projects.delete(id);
  }

  public addMember(projectId: ProjectId, userId: UserId): Project | undefined {
    const project = this.projects.get(projectId);
    if (project && !project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.eventBus.publish({ name: 'project.memberAdded', payload: { projectId, userId } });
      return project;
    }
    return undefined;
  }

  public removeMember(projectId: ProjectId, userId: UserId): Project | undefined {
    const project = this.projects.get(projectId);
    if (project) {
      const initialLength = project.memberIds.length;
      project.memberIds = project.memberIds.filter(id => id !== userId);
      if (project.memberIds.length < initialLength) {
        // Member was actually removed
        return project;
      }
    }
    return undefined;
  }
}

import { Task, TaskId, ProjectId, UserId, TaskStatus } from './types';
import { EventBus } from './event-bus.js'; // Corrected import with .js extension
import { generateId } from './utils';

export class TaskService {
  private tasks: Map<TaskId, Task> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
    // Seed some initial data
    const task1 = this.createTask({
      projectId: 'project1', // Assuming 'project1' is a valid ProjectId for demo purposes
      title: 'Design Homepage Mockups',
      description: 'Create initial mockups for the new homepage design.',
      status: 'todo',
      assigneeId: 'user1',
    });
    if (task1) {
      // These operations will publish events, which NotificationService will pick up.
      this.assignTask(task1.id, 'user2'); // Change assignee to 'user2'
      this.updateTaskStatus(task1.id, 'in-progress');
    }
  }

  public createTask(taskData: {
    projectId: ProjectId;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId?: UserId;
  }): Task {
    const newTask: Task = {
      id: generateId(),
      ...taskData,
    };
    this.tasks.set(newTask.id, newTask);
    return newTask;
  }

  public getTask(id: TaskId): Task | undefined {
    return this.tasks.get(id);
  }

  public getTasksByProject(projectId: ProjectId): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  public getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  public updateTask(id: TaskId, updates: Partial<Omit<Task, 'id' | 'projectId'>>): Task | undefined {
    const task = this.tasks.get(id);
    if (task) {
      Object.assign(task, updates);
      return task;
    }
    return undefined;
  }

  public deleteTask(id: TaskId): boolean {
    return this.tasks.delete(id);
  }

  public updateTaskStatus(taskId: TaskId, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(taskId);
    if (!task) {
      return undefined;
    }

    const oldStatus = task.status;

    // Status transition validation
    if (oldStatus === 'todo' && newStatus === 'done') {
      throw new Error('Cannot transition directly from todo to done.');
    }
    if (oldStatus === 'in-progress' && newStatus === 'todo') {
      throw new Error('Cannot transition from in-progress to todo.');
    }
    if (oldStatus === 'done' && newStatus !== 'done') {
      throw new Error('Cannot transition out of done status.');
    }
    if (oldStatus === newStatus) {
      return task; // No change needed
    }

    task.status = newStatus;
    this.eventBus.publish({ name: 'task.statusChanged', payload: { taskId, previousStatus: oldStatus, newStatus } });
    return task;
  }

  public assignTask(taskId: TaskId, assigneeId: UserId): Task | undefined {
    const task = this.tasks.get(taskId);
    if (task) {
      const previousAssigneeId = task.assigneeId;
      if (previousAssigneeId !== assigneeId) {
        task.assigneeId = assigneeId;
        this.eventBus.publish({ name: 'task.assigned', payload: { taskId, assigneeId, previousAssigneeId } });
      }
      return task;
    }
    return undefined;
  }
}
